text:
Este provider sincroniza Lenis con el ticker de GSAP, actualiza ScrollTrigger en cada desplazamiento y limpia todas las suscripciones correctamente.

```tsx
// components/providers/smooth-scroll-provider.tsx
"use client";

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import Lenis from "lenis";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const LenisContext = createContext<Lenis | null>(null);

type SmoothScrollProviderProps = {
  children: ReactNode;
};

export function SmoothScrollProvider({
  children,
}: SmoothScrollProviderProps) {
  const [lenis, setLenis] = useState<Lenis | null>(null);

  useEffect(() => {
    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;

    if (reducedMotion) {
      ScrollTrigger.refresh();
      return;
    }

    const instance = new Lenis({
      lerp: 0.1,
      smoothWheel: true,
      anchors: true,
      autoRaf: false,
    });

    const updateScrollTrigger = () => {
      ScrollTrigger.update();
    };

    const updateLenis = (time: number) => {
      instance.raf(time * 1000);
    };

    instance.on("scroll", updateScrollTrigger);
    gsap.ticker.add(updateLenis);
    gsap.ticker.lagSmoothing(0);

    setLenis(instance);
    ScrollTrigger.refresh();

    return () => {
      instance.off("scroll", updateScrollTrigger);
      gsap.ticker.remove(updateLenis);
      gsap.ticker.lagSmoothing(500, 33);
      instance.destroy();
      setLenis(null);
    };
  }, []);

  return (
    <LenisContext.Provider value={lenis}>
      {children}
    </LenisContext.Provider>
  );
}

export function useLenis() {
  return useContext(LenisContext);
}
```

Importa los estilos de Lenis y monta el provider en el layout raíz:

```tsx
// app/layout.tsx
import "lenis/dist/lenis.css";

import { SmoothScrollProvider } from "@/components/providers/smooth-scroll-provider";

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="es">
      <body>
        <SmoothScrollProvider>
          {children}
        </SmoothScrollProvider>
      </body>
    </html>
  );
}
```

No hace falta `scrollerProxy`: Lenis mantiene el scroll nativo del documento. La sincronización recomendada es `lenis.on("scroll", ScrollTrigger.update)` más `lenis.raf(time * 1000)` dentro del ticker de GSAP. [Lenis](https://github.com/darkroomengineering/lenis), [ScrollTrigger](https://gsap.com/docs/v3/Plugins/ScrollTrigger/).
